CREATE TABLE IF NOT EXISTS public.push_tokens (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, token TEXT NOT NULL, platform TEXT DEFAULT 'web', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (user_id, token)); GRANT SELECT, INSERT, UPDATE, DELETE ON public.push_tokens TO authenticated; GRANT ALL ON public.push_tokens TO service_role; ALTER TABLE public.push_tokens ENABLE ROW LEVEL SECURITY; CREATE POLICY "Users manage their own push tokens" ON public.push_tokens FOR ALL TO authenticated USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);